<?php
/** TEMP PS S1631 run r2 — R: nerastų analizė (trim, variacijos, LIKE paieška pagal bazinį SKU). READ-ONLY. */
add_action('init', function(){
  if (!isset($_GET['ps_s1631r2'])) return;
  $o=array('v'=>'S1631 r2'); global $wpdb; $p=$wpdb->prefix;
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $csv=gzdecode(base64_decode('')); $eil=array_filter(explode("\n",$csv));
  $sk=$wpdb->get_results("SELECT pm.meta_value sku, pm.post_id, po.post_type FROM {$p}postmeta pm JOIN {$p}posts po ON po.ID=pm.post_id AND po.post_type IN('product','product_variation') WHERE pm.meta_key='_sku' AND pm.meta_value<>''");
  $map=array(); foreach($sk as $r){ $map[(string)$r->sku]=array((int)$r->post_id,$r->post_type); }
  $gid=$wpdb->get_col("SELECT DISTINCT pm.meta_value FROM {$p}postmeta pm JOIN {$p}posts po ON po.ID=pm.post_id WHERE pm.meta_key='_global_unique_id' AND pm.meta_value<>''");
  $gset=array_flip($gid);
  $ner=array();
  foreach($eil as $l){ $c=explode(';',$l); $s=$c[0]; $e=trim($c[1]??''); $q=(int)($c[2]??0);
    if(isset($map[$s])) continue; if($e!=='' && isset($gset[$e])) continue;
    $st=trim($s); $k=array('sku'=>$s,'q'=>$q);
    if($st!==$s && isset($map[$st])){ $k['trim']=$map[$st]; $ner[]=$k; continue; }
    // bazinis be _priesagos
    if(preg_match('/^(.*)_(\d+)$/',$st,$m)){ $k['baze']=isset($map[$m[1]])?$map[$m[1]]:null;
      // gal variacija su kitu sku formatu — LIKE
      $like=$wpdb->get_results($wpdb->prepare("SELECT pm.meta_value sku, pm.post_id, po.post_type FROM {$p}postmeta pm JOIN {$p}posts po ON po.ID=pm.post_id AND po.post_type IN('product','product_variation') WHERE pm.meta_key='_sku' AND pm.meta_value LIKE %s LIMIT 3", '%'.$wpdb->esc_like($m[2]).'%'));
      $k['like_gale']=array_map(function($x){return $x->sku.'#'.$x->post_id.'/'.$x->post_type;},$like);
    }
    $ner[]=$k;
  }
  $o['nerasta_n']=count($ner); $o['nerasta']=$ner;
  $o['variaciju_wp']=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}posts WHERE post_type='product_variation' AND post_status='publish'");
  $o['variable_wp']=(int)$wpdb->get_var("SELECT COUNT(DISTINCT p.ID) FROM {$p}posts p JOIN {$p}term_relationships r ON r.object_id=p.ID JOIN {$p}term_taxonomy tt ON tt.term_taxonomy_id=r.term_taxonomy_id JOIN {$p}terms t ON t.term_id=tt.term_id WHERE tt.taxonomy='product_type' AND t.slug='variable' AND p.post_type='product'");
  header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE); exit;
},99);
